/* menu/src/uifont.h -- the menu's proportional anti-aliased UI faces: a build-time 4 bpp coverage atlas
 * (menu/src/uifont_data.c, generated by tools/omsat/uifont.py from Noto Sans JP, OFL) and a portable rasteriser that
 * measures a string and draws it into a 4 bpp buffer. The Saturn side (menu/ui/uitext.c) uploads that buffer as a VDP1
 * 16-colour lookup-table sprite. Portable C, host-tested (menu/host-tests/test_uifont.c). BSD-3-Clause. */
#ifndef OM_UIFONT_H
#define OM_UIFONT_H
#include <stdint.h>

#define OM_UF_NGLYPH 98          /* ASCII 0x20-0x7E, then U+203A, U+00B7, U+2026 */
#define OM_UF_RSAQUO 95          /* › */
#define OM_UF_MIDDOT 96          /* · */
#define OM_UF_ELLIPSIS 97        /* … */

typedef struct { uint8_t w, h; int8_t xoff, yoff; uint8_t adv8, pad; uint16_t off; } om_glyph;   /* adv8: 1/8 px */
typedef struct { uint8_t asc, desc; int8_t mid, pad; const om_glyph *g; const uint8_t *bits; } om_face;
typedef struct { uint8_t w, h; const uint8_t *bits; } om_icon;      /* 4 bpp, stride (w + 1) / 2 */

enum { OM_FACE_ITEM, OM_FACE_SEL, OM_FACE_SMALL, OM_FACE_TITLE, OM_FACE_BRAND, OM_FACE_LABEL, OM_FACE_HERO,
       OM_FACE_LABEL8, OM_FACE_COUNT };   /* LABEL, HERO: Task 13c's loading screen; LABEL8: Task 13d's interstitial */
extern const om_face om_face_item, om_face_sel, om_face_small, om_face_title, om_face_brand, om_face_label,
    om_face_hero, om_face_label8;
extern const om_icon om_icon_folder, om_icon_star, om_icon_badge_a, om_icon_badge_b, om_icon_badge_x,
    om_icon_badge_y, om_icon_badge_z, om_icon_badge_st, om_icon_badge_c, om_icon_badge_l, om_icon_badge_r,
    om_icon_wordmark, om_icon_wordmark_s;   /* "AETHER" in Montserrat (uifont.py WORDMARKS): header; loading footer */
extern const uint32_t om_uifont_bytes;

/* Region flags (addendum 6): 16x8 4 bpp, the 12x8 flag in columns 4..15 (RGB codes). In
 * IP.BIN area-code order J T U B K A E L. rgb[i] is LUT entry i + 1. */
#define OM_NFLAGS 8
#define OM_FLAG_TEX_W 16
#define OM_FLAG_W 12
#define OM_FLAG_H 8
typedef struct { char code; const uint8_t *bits; uint16_t rgb[15]; } om_flag;   /* not "pal": SGL.H #defines it */
extern const om_flag om_flags[OM_NFLAGS];
const om_flag *om_flag_for(char area_code);              /* NULL for anything but J T U B K A E L */

const om_face *om_face_get(int id);
/* Decodes the next character of a UTF-8 (or ASCII) string to a glyph index and advances *s; -1 at the terminator.
 * Anything outside the charset (including malformed UTF-8) is '?'. */
int om_uf_next(const char **s);
/* Width in pixels of s set in face f: the larger of the pen's end and the last glyph's ink. */
int om_uf_width(const om_face *f, const char *s);
/* Line height (ascent + descent) and the baseline's offset below a box's vertical middle (Pillow's "lm" anchor). */
int om_uf_height(const om_face *f);
/* Draws s into a 4 bpp buffer (stride_px pixels a row, rows h, high nibble = left pixel) with its pen starting at
 * (x, base) where base is the baseline row; coverage combines by max; pixels outside [0,w)x[0,h) are clipped. Returns
 * the pen's end x. The buffer is not cleared. */
int om_uf_draw(const om_face *f, const char *s, uint8_t *buf, int stride_px, int w, int h, int x, int base);
/* Letter-spaced (Task 13c's "NOW LOADING"): every advance grows by track8 / 8 px. */
int om_uf_width_tracked(const om_face *f, const char *s, int track8);
int om_uf_draw_tracked(const om_face *f, const char *s, uint8_t *buf, int stride_px, int w, int h, int x, int base,
                       int track8);
/* Draws a 4 bpp icon at (x, y) into the same kind of buffer (max-combine, clipped). */
void om_uf_icon(const om_icon *ic, uint8_t *buf, int stride_px, int w, int h, int x, int y);
/* Fade-clip (addendum 3): attenuate the coverage of columns [from_x, from_x + len) in a linear ramp to nothing, for text
 * cut at its box's right edge. Long text is never abbreviated: there is no ellipsis function. */
void om_uf_fade(uint8_t *buf, int stride_px, int h, int from_x, int len);
#endif
